window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ba5b02f7604f58b"]={"versions": [{"id": "FIG-3ba5b02f7604f58b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das Modul <code>FrArTp</code> (FlexRay Transport Protocol). Dargestellt ist das Metamodell für den Konfigurationscontainer <code>FrArTpConnection</code> und dessen Sub-Container, Parameter sowie Referenzen auf globale PDU-Definitionen (<code>EcucPdu</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Hauptcontainer ist <code>FrArTpConnection</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\"><li><code>FrArTpLa</code> (<code>EcucIntegerParamDef</code>): Min. 0, Max. 65535, Multiplizität 0..1.\n</li><li><code>FrArTpRa</code> (<code>EcucIntegerParamDef</code>): Min. 0, Max. 65535, Multiplizität 0..1.\n</li><li><code>FrArTpMultRec</code> (<code>EcucBooleanParamDef</code>): Boolescher Schalter für Mehrfachempfang.\n</li><li><code>FrArTpConPrioPdus</code> (<code>EcucIntegerParamDef</code>): Min. 0, Max. 255, Multiplizität 0..1, <code>defaultValue = 0</code>.\n</li></ul>\n<p class=\"fig-p\">Sub-Container (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\"><li><code>FrArTpTxSdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpSduTxId</code> (<code>EcucIntegerParamDef</code>, min = 0, max = 65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>FrArTpTxSduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel (<code>+destination</code>) auf <code>Pdu</code> (<code>EcucParamConfContainerDef</code> aus <code>EcucPdu</code>, Multiplizität 0..*).\n</li></ul>\n</li><li><code>FrArTpRxSdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpSduRxId</code> (<code>EcucIntegerParamDef</code>, min = 0, max = 65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>FrArTpRxSduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel (<code>+destination</code>) auf <code>Pdu</code> (<code>EcucParamConfContainerDef</code> aus <code>EcucPdu</code>, Multiplizität 0..*).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeitinteraktion. Die Konfiguration bestimmt zur Generierungs- und Initialisierungszeit die Adressierungsbeziehungen (Local Address <code>FrArTpLa</code>, Remote Address <code>FrArTpRa</code>), Priorisierung und PDU-Zuordnungen für Sende- und Empfangsverbindungen des FlexRay-Transportprotokolls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Vorgaben für Codegeneratoren und Konfigurationswerkzeuge gemäß AUTOSAR-ECUC-Standard. <code>FrArTpConnection</code> muss mindestens einmal konfiguriert werden (1..*). Sende- und Empfangs-SDU-Container sind jeweils optional (0..1), erfordern bei Vorhandensein aber zwingend eine gültige Referenz (1..1) auf ein Pdu-Element sowie eindeutige numerische Identifier (<code>FrArTpSduTxId</code>, <code>FrArTpSduRxId</code>) als symbolische Namen. Unterstützte Konfigurationsvarianten umfassen <code>VARIANT-PRE-COMPILE</code> und <code>VARIANT-POST-BUILD</code>.</p>"}, {"id": "FIG-a580b6a4d5bf1a17", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das Modul <code>FrArTp</code> (FlexRay Transport Protocol). Dargestellt ist das Metamodell für den Konfigurationscontainer <code>FrArTpConnection</code> und dessen Sub-Container, Parameter sowie Referenzen auf globale PDU-Definitionen (<code>EcucPdu</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Hauptcontainer ist <code>FrArTpConnection</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter (<code>+parameter</code>):</p>\n<ul class=\"fig-list\"><li><code>FrArTpLa</code> (<code>EcucIntegerParamDef</code>): Min. 0, Max. 65535, Multiplizität 0..1.\n</li><li><code>FrArTpRa</code> (<code>EcucIntegerParamDef</code>): Min. 0, Max. 65535, Multiplizität 0..1.\n</li><li><code>FrArTpMultRec</code> (<code>EcucBooleanParamDef</code>): Boolescher Schalter für Mehrfachempfang.\n</li><li><code>FrArTpConPrioPdus</code> (<code>EcucIntegerParamDef</code>): Min. 0, Max. 255, Multiplizität 0..1, <code>defaultValue = 0</code>.\n</li></ul>\n<p class=\"fig-p\">Sub-Container (<code>+subContainer</code>):</p>\n<ul class=\"fig-list\"><li><code>FrArTpTxSdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpSduTxId</code> (<code>EcucIntegerParamDef</code>, min = 0, max = 65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>FrArTpTxSduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel (<code>+destination</code>) auf <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n</li><li><code>FrArTpRxSdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1):\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpSduRxId</code> (<code>EcucIntegerParamDef</code>, min = 0, max = 65535, <code>symbolicNameValue = true</code>).\n</li><li>Referenz <code>FrArTpRxSduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel (<code>+destination</code>) auf <code>Pdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell ohne Laufzeitinteraktion. Die Konfiguration bestimmt zur Generierungs- und Initialisierungszeit die Adressierungsbeziehungen (Local Address <code>FrArTpLa</code>, Remote Address <code>FrArTpRa</code>), Priorisierung und PDU-Zuordnungen für Sende- und Empfangsverbindungen des FlexRay-Transportprotokolls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Vorgaben für Codegeneratoren und Konfigurationswerkzeuge gemäß AUTOSAR-ECUC-Standard. <code>FrArTpConnection</code> muss mindestens einmal konfiguriert werden (1..*). Sende- und Empfangs-SDU-Container sind jeweils optional (0..1), erfordern bei Vorhandensein aber zwingend eine gültige Referenz (1..1) auf ein Pdu-Element sowie eindeutige numerische Identifier (<code>FrArTpSduTxId</code>, <code>FrArTpSduRxId</code>) als symbolische Namen. Unterstützte Konfigurationsvarianten umfassen <code>VARIANT-PRE-COMPILE</code> und <code>VARIANT-POST-BUILD</code>.</p>"}], "trans": [{"from": "FIG-3ba5b02f7604f58b", "to": "FIG-a580b6a4d5bf1a17", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Container <code>Pdu</code>: Paketursprungshinweis <code>(from EcucPdu)</code> unterhalb des Containers entfernt.\n</li><li>Typbezeichner: Leerzeichen vor dem Doppelpunkt in den Klassennamen vereinheitlicht/entfernt (z. B. <code>FrArTpConnection: EcucParamConfContainerDef</code> statt <code>FrArTpConnection : EcucParamConfContainerDef</code>).\n</li></ul>"}]};
